root.command:
IF OBJECT_ID(N'dbo.DeliveryVisitTbl', N'U') IS NOT NULL AND OBJECT_ID(N'dbo.MobileDeliveryProofTbl', N'U') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.DeliveryVisitTbl) AND EXISTS (SELECT 1 FROM dbo.MobileDeliveryProofTbl WHERE ContactID IS NOT NULL) BEGIN INSERT INTO dbo.DeliveryVisitTbl (VisitDate, PersonID, ContactID, FirstAt, LastAt, Stops) SELECT CAST(p.DeliveredAt AS DATE), COALESCE(p.PersonID, o.ToBeDeliveredByID, 0), p.ContactID, MIN(p.DeliveredAt), MAX(p.DeliveredAt), 0 FROM dbo.MobileDeliveryProofTbl p INNER JOIN dbo.OrdersTbl o ON o.OrderID = p.OrderID WHERE p.ContactID IS NOT NULL AND p.ContactID <> 9 -- 9 = sundry (walk-in) contact GROUP BY CAST(p.DeliveredAt AS DATE), COALESCE(p.PersonID, o.ToBeDeliveredByID, 0), p.ContactID;
;WITH r AS ( SELECT Position, ROW_NUMBER() OVER (PARTITION BY VisitDate, PersonID ORDER BY FirstAt, ContactID) AS rn FROM dbo.DeliveryVisitTbl) UPDATE r SET Position = rn;
UPDATE v SET Stops = CASE WHEN ISNULL(pl.n, 0) > vc.n THEN pl.n ELSE vc.n END FROM dbo.DeliveryVisitTbl v CROSS APPLY (SELECT COUNT(*) AS n FROM dbo.DeliveryVisitTbl v2 WHERE v2.VisitDate = v.VisitDate AND v2.PersonID = v.PersonID) vc OUTER APPLY (SELECT COUNT(DISTINCT o.ContactID) AS n FROM dbo.OrdersTbl o WHERE o.ToBeDeliveredByID = v.PersonID AND CAST(o.RequiredByDate AS DATE) = v.VisitDate) pl; END
